delete from public.tiktok_posts a using public.tiktok_posts b where a.post_url = b.post_url and a.ctid > b.ctid;
create unique index if not exists tiktok_posts_post_url_key on public.tiktok_posts(post_url);
insert into public.tiktok_posts (post_url, shortcode, caption, like_count, comments_count, share_count, view_count, timestamp, owner_username, media_type, scrape_status, scraped_at)
select v.post_url, v.shortcode, v.caption, v.like_count::int, v.comments_count::int, v.share_count::int, v.view_count::int, v.timestamp::timestamptz, v.owner_username, v.media_type, 'scraped', now()
